package nexutils;

import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

import javax.inject.Inject;
import java.awt.*;
import java.awt.image.BufferedImage;

public class AltarOverlay extends Overlay {
	private final NexUtilsPlugin plugin;
	private final NexUtilsConfig config;
	private final Client client;
	public static final Color CLICKBOX_FILL_COLOR = new Color(205, 50, 50, 50);

	@Inject
	AltarOverlay(NexUtilsPlugin plugin, NexUtilsConfig config, Client client) {
		super(plugin);

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);

		this.plugin = plugin;
		this.config = config;
		this.client = client;
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		if (!config.altarPreventNoZarosItem() || plugin.altarObject == null) {
			return null;
		}

		if (plugin.isZarosItemEquipped()) {
			return null;
		}

		Point mousePosition = client.getMouseCanvasPosition();
		if (client.getTopLevelWorldView().getPlane() == plugin.altarObject.getPlane()) {
			// Draw image on the object
			Point baseImageLocation = plugin.altarObject.getCanvasTextLocation(graphics, "", 125);

			if (baseImageLocation == null) {
				return null;
			}
			BufferedImage generatedEntranceOverlayImage = plugin.getAltarOverlayImage();
			int xOffset = generatedEntranceOverlayImage.getWidth() / 2;
			int yOffset = generatedEntranceOverlayImage.getHeight() / 2;

			Point imageLocation = new Point(baseImageLocation.getX() - xOffset, baseImageLocation.getY() - yOffset);
			OverlayUtil.renderImageLocation(graphics, imageLocation, generatedEntranceOverlayImage);

			// Fill the object with colour
			OverlayUtil.renderHoverableArea(graphics, plugin.altarObject.getClickbox(), mousePosition,
				CLICKBOX_FILL_COLOR, // fill colour
				Color.BLACK, // border
				Color.BLACK // hover border
			);
		}

		return null;
	}
}

package nexutils;

import java.util.Set;

public class Constants {
	static final Set<Integer> BLOOD_REAVER_ATTACK_SOUNDS = Set.of(
		5278,   // nex2021_blood_reaver_attack
		110,    // blood_rush_impact
		106     // blood_cast
	);

	static final int NEX_ARENA_REGION = 11601;
}

package nexutils;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(NexUtilsConfig.GROUP_KEY)
public interface NexUtilsConfig extends Config {
	String GROUP_KEY = "nex-utils";

	String ALTAR_LEFT_CLICK_TP = "altar-left-click-tp";
	String ALTAR_PREVENT_NO_ZAROS_ITEM = "altar-prevent-no-zaros-item";

	String ENTRANCE_PREVENT_EMPTY_INV = "entrance-prevent-empty-inv";
	String ENTRANCE_PREVENT_CHUGGING_BARREL = "entrance-prevent-chugging-barrel";
	String ENTRANCE_PREVENT_SATURATED_HEART = "entrance-prevent-saturated-heart";
	String ENTRANCE_PREVENT_NO_BOTD = "entrance-prevent-no-botd";

	String MUTE_BLOOD_REAVERS = "mute-blood-reavers";
	String REOPEN_CHAT_ON_FINISH = "reopen-chat-on-finish";

	@ConfigSection(
		name = "Altar",
		description = "Changes related to the zarosian altar",
		position = 0,
		closedByDefault = false
	)
	String altarSection = "Altar";

	@ConfigSection(
		name = "Entrance prevention",
		description = "Changes helping to avoid entering with wrong inventory",
		position = 5,
		closedByDefault = false
	)
	String entrancePreventSection = "Entrance prevention";

	@ConfigSection(
		name = "Miscellaneous",
		description = "Uncategorized changes",
		position = 10,
		closedByDefault = false
	)
	String miscSection = "Miscellaneous";

	@ConfigItem(
		keyName = ALTAR_LEFT_CLICK_TP,
		name = "Left click tp when not in fight",
		description = "Swaps left click on the altar to 'Teleport' when Nex isn't present.<br>"
			+ "NOTE: This setting will still take effect if Nex spawns but hasn't been attacked yet (e.g. when leaving late)",
		position = 0,
		section = altarSection
	)
	default boolean altarLeftClickTp() {
		return false;
	}

	@ConfigItem(
		keyName = ALTAR_PREVENT_NO_ZAROS_ITEM,
		name = "Prevent use with no zaros item",
		description = "Deprioritizes usage of altar options when no zaros items are equipped.",
		position = 10,
		section = altarSection
	)
	default boolean altarPreventNoZarosItem() {
		return true;
	}

	@ConfigItem(
		keyName = ENTRANCE_PREVENT_EMPTY_INV,
		name = "Non-full inventory",
		description = "Deprioritizes usage of entrance barrier to Nex arena when your inventory isn't completely full.<br>"
			+ "Helps if you accidentally don't withdraw e.g. food items after pre-potting.",
		position = 0,
		section = entrancePreventSection
	)
	default boolean entrancePreventEmptyInv() {
		return true;
	}

	@ConfigItem(
		keyName = ENTRANCE_PREVENT_CHUGGING_BARREL,
		name = "Chugging barrel",
		description = "Deprioritizes usage of entrance barrier to Nex arena when<br>"
			+ "Chugging barrel is present in your inventory.",
		position = 10,
		section = entrancePreventSection
	)
	default boolean entrancePreventChuggingBarrel() {
		return true;
	}

	@ConfigItem(
		keyName = ENTRANCE_PREVENT_SATURATED_HEART,
		name = "Saturated/Imbued heart",
		description = "Deprioritizes usage of entrance barrier to Nex arena when<br>"
			+ "Saturated or Imbued heart is present in your inventory.",
		position = 20,
		section = entrancePreventSection
	)
	default boolean entrancePreventSaturatedHeart() {
		return true;
	}

	@ConfigItem(
		keyName = ENTRANCE_PREVENT_NO_BOTD,
		name = "No Book of the dead",
		description = "Deprioritizes usage of entrance barrier to Nex arena when<br>"
			+ "Book of the dead is NOT present in your inventory.",
		position = 30,
		section = entrancePreventSection
	)
	default boolean entrancePreventNoBOTD() {
		return true;
	}

	@ConfigItem(
		keyName = MUTE_BLOOD_REAVERS,
		name = "Mute Blood Reavers in kc room",
		description = "Mutes Blood Reaver attacks in the minion room before bank.",
		position = 0,
		section = miscSection
	)
	default boolean muteBloodReavers() {
		return false;
	}

	@ConfigItem(
		keyName = REOPEN_CHAT_ON_FINISH,
		name = "Open game chat when Nex dies",
		description = "Opens game chat upon a successful kill.<br>"
			+ "Aims to help to include kill time & mvp status for loot screenshots.",
		position = 20,
		section = miscSection
	)
	default boolean reopenChatOnFinish() {
		return false;
	}
}

package nexutils;

import com.google.inject.Provides;

import javax.annotation.Nullable;
import javax.inject.Inject;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.SoundEffectPlayed;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Comparator;

@Slf4j
@PluginDescriptor(
	name = "Nex Utilities",
	description = "Miscellaneous edits/additions related to Nex.",
	tags = {"nex", "nexling", "utilities", "additions", "blood reavers", "altar"}
)
public class NexUtilsPlugin extends Plugin {
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private NexUtilsConfig config;

	@Inject
	private AltarOverlay altarOverlay;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ItemManager itemManager;

	@Nullable
	public GameObject altarObject;
	@Getter
	private BufferedImage altarOverlayImage;
	@Getter
	private boolean zarosItemEquipped = false;

	// Entrance prevention flags
	private boolean entrancePreventEmptyInventorySlots = false;
	private boolean entrancePreventChuggingBarrel = false;
	private boolean entrancePreventSaturatedHeart = false;
	private boolean entrancePreventNoBOTD = false;


	private boolean isNexFightActive = false;
	private int lastNexBarrierValue = 0; // default value for the NEX_BARRIER varbit

	private static String menuEntryColor(String optionText) {
		return ColorUtil.wrapWithColorTag(optionText, new Color(255, 106, 213, 255).brighter());
	}

	private final Comparator<MenuEntry> ALTAR_TP_OPTION =
		Comparator.comparing(me -> me.getIdentifier() == ObjectID.NEX_ZAROS_ALTAR && me.getOption().equals("Teleport"));

	@Override
	protected void startUp() throws Exception {
		log.debug("Nex Utils started!");
		altarOverlayImage = combineItemImages(
			resize(ImageUtil.loadImageResource(getClass(), "zaros_logo.png"), 36, 32), // use same dimensions as an item sprite
			itemManager.getImage(ItemID.BANK_FILLER)
		);
		overlayManager.add(altarOverlay);

		clientThread.invoke(() -> {
			final ItemContainer wornItems = client.getItemContainer(InventoryID.WORN);
			if (wornItems != null) {
				zarosItemEquipped = checkAnyZarosItemEquipped(wornItems);
			}

			final ItemContainer inventoryItems = client.getItemContainer(InventoryID.INV);
			if (inventoryItems != null) {
				checkInventorySlots(inventoryItems);
			}
		});
	}

	@Override
	protected void shutDown() throws Exception {
		isNexFightActive = false;
		altarObject = null;
		altarOverlayImage = null;
		overlayManager.remove(altarOverlay);
		log.debug("Nex Utils stopped!");
	}

	@Provides
	NexUtilsConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(NexUtilsConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e) {
		if (e.getGameState() == GameState.LOGGING_IN || e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING) {
			altarObject = null;
		}
		if (e.getGameState() == GameState.LOGGED_IN && (!client.getTopLevelWorldView().isInstance() && client.getLocalPlayer().getWorldLocation().getRegionID() != Constants.NEX_ARENA_REGION)) {
			log.debug("altar is being set to null! {} {} {}", client.getLocalPlayer().getWorldLocation(), client.getLocalPlayer().getWorldLocation().getRegionID(), client.getTopLevelWorldView().isInstance());
			altarObject = null;
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event) {
		if (event.getGameObject().getId() == ObjectID.NEX_ZAROS_ALTAR) {
			altarObject = event.getGameObject();
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event) {
		if (event.getGameObject() != null && event.getGameObject().getId() == ObjectID.NEX_ZAROS_ALTAR) {
			altarObject = null;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		if (event.getContainerId() == InventoryID.WORN) {
			zarosItemEquipped = checkAnyZarosItemEquipped(event.getItemContainer());
		}

		if (event.getContainerId() == InventoryID.INV) {
			checkInventorySlots(event.getItemContainer());
		}
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort event) {
		if (altarObject == null) {
			return;
		}

		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length < 1) {
			return;
		}
		// Entries are always returned in "reverse" - top option is last
		MenuEntry topEntry = entries[entries.length - 1];

		if (topEntry.getIdentifier() == ObjectID.NEX_FIGHT_BARRIER && topEntry.getOption().startsWith("Pass (")) {
			if (entrancePreventEmptyInventorySlots && config.entrancePreventEmptyInv()) {
				deprioritizeMenuEntry(entries, menuEntryColor("Fill your inventory!"));
			}
			if (entrancePreventChuggingBarrel && config.entrancePreventChuggingBarrel()) {
				deprioritizeMenuEntry(entries, menuEntryColor("Bank your Chugging barrel!"));
			}
			if (entrancePreventSaturatedHeart && config.entrancePreventSaturatedHeart()) {
				deprioritizeMenuEntry(entries, menuEntryColor("Bank your Saturated heart!"));
			}
			if (entrancePreventNoBOTD && config.entrancePreventNoBOTD()) {
				deprioritizeMenuEntry(entries, menuEntryColor("Where's your Book of the dead?"));
			}
		} else if (topEntry.getIdentifier() == ObjectID.NEX_ZAROS_ALTAR) {
			if (!zarosItemEquipped && config.altarPreventNoZarosItem()) {
				deprioritizeMenuEntry(entries, menuEntryColor("Equip a zaros item!"));
			} else if (!isNexFightActive && config.altarLeftClickTp()) {
				// Sort entries by putting teleport option on top
				Menu menu = client.getMenu();
				menu.setMenuEntries(Arrays.stream(menu.getMenuEntries()).sorted(ALTAR_TP_OPTION).toArray(MenuEntry[]::new));
			}
		}
	}

	@Subscribe
	public void onSoundEffectPlayed(SoundEffectPlayed event) {
		if (!config.muteBloodReavers() || !Constants.BLOOD_REAVER_ATTACK_SOUNDS.contains(event.getSoundId())) {
			return;
		}

		if (isInKcRoom(client.getLocalPlayer().getWorldLocation())) {
			event.consume();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		if (event.getVarbitId() != VarbitID.NEX_BARRIER) {
			return;
		}
		int newValue = event.getValue();

		// Nex fight has either just ended or the player has left the fight
		if (lastNexBarrierValue == 3) {
			isNexFightActive = false;
			if (newValue == 2 && config.reopenChatOnFinish()) {
				// (3 -> 2) Nex died and fight was completed successfully, reopen chatbox if desired
				// Only toggle/open chat if it's not set to 'Game'
				if (client.getVarcIntValue(VarClientID.CHAT_VIEW) != 1) {
					// Script ID 175 - clientscript,chat_button_onop
					// argument #1 - operation to perform on selected chat tab (1 = opens the tab)
					// argument #2 - value of CHAT_VIEW / chat tab to open (1 = 'Game')
					clientThread.invokeLater(() -> client.runScript(175, 1, 1));
				}
			}
		}

		lastNexBarrierValue = newValue;
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event) {
		// Only proceed if we need to start a fight
		if (isNexFightActive || client.getVarbitValue(VarbitID.NEX_BARRIER) != 3) {
			return;
		}

		Actor actor = event.getActor();
		// When a hitsplat is applied to Nex, this means the fight is active
		// Checking for hitsplat works better in this case because if the intent is to leave, team will usually not attack her
		if (actor instanceof NPC && "Nex".equals(actor.getName())) {
			isNexFightActive = true;
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event) {
		if (!event.getCommand().equals("nu")) {
			return;
		}
		log.debug("empty slots? {} item {} altar obj {} fight active {} loc {} regID {} instance? {}", entrancePreventEmptyInventorySlots, zarosItemEquipped, altarObject, isNexFightActive,
			client.getLocalPlayer().getWorldLocation(), client.getLocalPlayer().getWorldLocation().getRegionID(), client.getTopLevelWorldView().isInstance());
	}

	// Check whether player is within bounds of room with ancient minions - the one before Nex bank
	private boolean isInKcRoom(WorldPoint position) {
		if (position.getX() >= 2849 && position.getX() <= 2899) {
			return position.getY() >= 5194 && position.getY() <= 5228;
		}
		return false;
	}

	// Check every item slot to see if we have god protection
	private boolean checkAnyZarosItemEquipped(ItemContainer container) {
		final Item weapon = container.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon != null && ZarosItems.Weapon.contains(weapon.getId())) {
			return true;
		}

		final Item offhand = container.getItem(EquipmentInventorySlot.SHIELD.getSlotIdx());
		if (offhand != null && ZarosItems.Offhand.contains(offhand.getId())) {
			return true;
		}

		final Item head = container.getItem(EquipmentInventorySlot.HEAD.getSlotIdx());
		if (head != null && ZarosItems.Head.contains(head.getId())) {
			return true;
		}

		final Item cape = container.getItem(EquipmentInventorySlot.CAPE.getSlotIdx());
		if (cape != null && ZarosItems.Cape.contains(cape.getId())) {
			return true;
		}

		final Item body = container.getItem(EquipmentInventorySlot.BODY.getSlotIdx());
		if (body != null && ZarosItems.Body.contains(body.getId())) {
			return true;
		}

		final Item legs = container.getItem(EquipmentInventorySlot.LEGS.getSlotIdx());
		if (legs != null && ZarosItems.Legs.contains(legs.getId())) {
			return true;
		}

		final Item hands = container.getItem(EquipmentInventorySlot.GLOVES.getSlotIdx());
		if (hands != null && ZarosItems.Gloves.contains(hands.getId())) {
			return true;
		}

		final Item feet = container.getItem(EquipmentInventorySlot.BOOTS.getSlotIdx());
		if (feet != null && ZarosItems.Boots.contains(feet.getId())) {
			return true;
		}

		final Item ammo = container.getItem(EquipmentInventorySlot.AMMO.getSlotIdx());
		if (ammo != null && ZarosItems.Ammo.contains(ammo.getId())) {
			return true;
		}

		final Item neck = container.getItem(EquipmentInventorySlot.AMULET.getSlotIdx());
		return neck != null && ZarosItems.Amulet.contains(neck.getId());
	}

	// Check inventory slots for empty ones and presence of other notable items that should prevent entering
	private void checkInventorySlots(ItemContainer inventoryItems) {
		boolean hasAnySlotEmpty = false;
		boolean hasChuggingBarrel = false;
		boolean hasSaturatedHeart = false;
		boolean hasBOTD = false;

		for (Item invItem : inventoryItems.getItems()) {
			switch (invItem.getId()) {
				// Check for empty item slot
				case -1:
					hasAnySlotEmpty = true;
					break;

				// Check for chugging barrel
				case ItemID.MM_PREPOT_DEVICE:
					hasChuggingBarrel = true;
					break;

				// Check for saturated or imbued heart
				case ItemID.IMBUED_HEART:
				case ItemID.SATURATED_HEART:
					hasSaturatedHeart = true;
					break;

				// Check for Book of the dead
				case ItemID.BOOK_OF_THE_DEAD:
					hasBOTD = true;
					break;
			}
		}

		entrancePreventEmptyInventorySlots = hasAnySlotEmpty;
		entrancePreventChuggingBarrel = hasChuggingBarrel;
		entrancePreventSaturatedHeart = hasSaturatedHeart;
		entrancePreventNoBOTD = !hasBOTD; // inverted, because the prevention boolean should indicate lack of BOTD
	}

	// Insert a dummy menu option and put rest of the options down
	private void deprioritizeMenuEntry(MenuEntry[] entries, String textToShow) {
		// Create list of new entries which will include new dummy option on top
		MenuEntry[] newEntries = new MenuEntry[entries.length + 1];
		System.arraycopy(entries, 0, newEntries, 0, entries.length);
		// Insert new dummy entry; putting it at the end makes it the top option
		newEntries[newEntries.length - 1] = client.getMenu().createMenuEntry(0).setType(MenuAction.CANCEL).setOption(textToShow).setTarget("");
		client.getMenu().setMenuEntries(newEntries);
	}

	public static BufferedImage resize(BufferedImage img, int newW, int newH) {
		BufferedImage resizedImg = new BufferedImage(newW, newH, img.getType());
		Graphics2D g = resizedImg.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(img, 0, 0, newW, newH, null);
		g.dispose();
		return resizedImg;
	}

	// Taken from escape crystal notify plugin: https://github.com/Xylot/escape-crystal-notify/blob/7038395a1c95d0a9ea0b083fd2648f2b90fab510/src/main/java/com/escapecrystalnotify/EscapeCrystalNotifyPlugin.java#L952-L970
	private BufferedImage combineItemImages(BufferedImage... images) {
		BufferedImage backgroundImage = images[0];

		BufferedImage result = new BufferedImage(backgroundImage.getWidth(), backgroundImage.getHeight(), BufferedImage.TYPE_INT_ARGB);

		Graphics2D graphics = result.createGraphics();

		graphics.setComposite(AlphaComposite.SrcOver);
		graphics.drawImage(backgroundImage, 0, 0, null);

		for (int i = 1; i < images.length; i++) {
			graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.7f));
			graphics.drawImage(images[i], 0, 0, null);
		}

		graphics.dispose();

		return result;
	}
}

